+                        <span class="step-label d-block mt-1 small text-success fw-semibold">@StepNames[step]</span>
+                    </button>
+                }
+                else
+                {
+                    <div>
+                        <span class="step-circle @(isCurrent ? "bg-primary text-white" : "bg-secondary text-white opacity-50")">@(step + 1)</span>
+                        <span class="step-label d-block mt-1 small @(isCurrent ? "fw-semibold text-primary" : "text-muted")">@StepNames[step]</span>
+                    </div>
+                }
+            </li>
+        }
+    </ol>
+</nav>
+
+@code {
+    private static readonly string[] StepNames = ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];
+
+    [Parameter, EditorRequired] public int CurrentStep { get; set; }
+    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = [];
+    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }
+}
