<h5 class="mb-3">References</h5>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Ref="@References[index]"
                   Index="@(index + 1)"
                   ShowRemove="@(References.Count > 1)"
                   OnChanged="r => UpdateRef(index, r)"
                   OnRemove="() => RemoveRef(index)" />
}

@if (References.Count < 3)
{
    <button type="button" class="btn btn-outline-secondary mb-3" @onclick="AddRef">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between mt-3">
    <button type="button" class="btn btn-outline-secondary" @onclick="OnBack">Back</button>
    <button type="button" class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Reference> References { get; set; } = [];
    [Parameter, EditorRequired] public EventCallback<List<Reference>> OnChanged { get; set; }
    [Parameter, EditorRequired] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }

    private string? ValidationError;

    private void UpdateRef(int index, Reference updated)
    {
        var list = new List<Reference>(References);
        list[index] = updated;
        OnChanged.InvokeAsync(list);
    }

    private void RemoveRef(int index)
    {
        var list = new List<Reference>(References);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddRef()
    {
        if (References.Count >= 3) return;
        var list = new List<Reference>(References)
        {
            new("", "", "", "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ValidationError = null;

        if (References.Count < 2)
        {
            ValidationError = "Please provide at least 2 references.";
            return;
        }

        if (References.Any(r => string.IsNullOrWhiteSpace(r.Name) ||
                                string.IsNullOrWhiteSpace(r.Relationship) ||
                                string.IsNullOrWhiteSpace(r.Email)))
        {
            ValidationError = "Each reference requires a name, relationship, and email.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

