@page "/apply"
@using sv_a6ee9df7e9b44f929234f28ac9b67d10.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h3 class="mb-4">Job Application</h3>

    @if (_submittedId is not null)
    {
        <div class="alert alert-success text-center">
            <h4 class="alert-heading">Application Submitted!</h4>
            <p class="mb-0">Your application has been received. Your application ID is <strong>#@_submittedId</strong>.</p>
        </div>
    }
    else
    {
        <StepIndicator CurrentStep="_currentStep"
                       CompletedSteps="_completedSteps"
                       OnStepClicked="GoToStep" />

        @if (!string.IsNullOrEmpty(_submitError))
        {
            <div class="alert alert-danger">@_submitError</div>
        }

        @switch (_currentStep)
        {
            case 0:
                <PersonalInfoStep Info="_personalInfo"
                                  OnChanged="info => _personalInfo = info"
                                  OnNext="NextFromStep"
                                  ValidateEmail="ApplicationService.ValidateEmailAsync" />
                break;

            case 1:
                <WorkHistoryStep Entries="_workEntries"
                                 OnChanged="entries => _workEntries = entries"
                                 OnNext="NextFromStep"
                                 OnBack="PreviousStep" />
                break;

            case 2:
                <ReferencesStep References="_references"
                                OnChanged="refs => _references = refs"
                                OnNext="NextFromStep"
                                OnBack="PreviousStep" />
                break;

            case 3:
                <CoverLetterStep CoverLetter="_coverLetter"
                                 OnChanged="cl => _coverLetter = cl"
                                 OnNext="NextFromStep"
                                 OnBack="PreviousStep" />
                break;

            case 4:
                <ReviewStep Personal="_personalInfo"
                            Work="@(new WorkHistory(_workEntries))"
                            References="_references"
                            CoverLetter="_coverLetter"
                            IsSubmitting="_isSubmitting"
                            OnEditSection="GoToStep"
                            OnSubmit="SubmitApplication"
                            OnBack="PreviousStep" />
                break;
        }
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = [];

    private PersonalInfo _personalInfo = new("", "", "", "");
    private List<WorkEntry> _workEntries = [new("", "", default, null, "")];
    private List<Reference> _references = [new("", "", "", ""), new("", "", "", "")];
    private string _coverLetter = "";

    private bool _isSubmitting;
    private int? _submittedId;
    private string? _submitError;

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _currentStep = step;
        }
    }

    private void NextFromStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0)
            _currentStep--;
    }

    private async Task SubmitApplication()
    {
        _isSubmitting = true;
        _submitError = null;

        try
        {
            var application = new JobApplication(
                _personalInfo,
                new WorkHistory(_workEntries),
                _references,
                _coverLetter
            );

            _submittedId = await ApplicationService.SubmitApplicationAsync(application);
        }
        catch (Exception ex)
        {
            _submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

